RAW = pd.read_csv(O / 'raw_temporal_metrics_mean_by_entry.csv', index_col=0); MECH = pd.read_csv(O / 'acf_abs_mechanism.csv', index_col=0); PUBM = pd.read_csv(O / 'published_acf_absolute_mae_by_model.csv', index_col=0)
PROV = json.load(open(O / 'baseline_provenance.json')); VER = json.load(open(O / 'verify_no_oracle.json')); VAL = json.load(open(O / 'validation_vs_phase_b.json'))
nm = {CTRL: 'shuffled control', 'iid': 'iid bootstrap (historical simulation)', 'sb_r': 'stationary block bootstrap (Politis–White on returns)', 'sb_abs': 'stationary block bootstrap, long blocks (Politis–White on |returns|)'}
